  1	import java.io.PrintStream;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	
  6	final class MST {
  7	    private static final int NO_EDGE = 0;
  8	    private static final int ROOT_PARENT = -1;
  9	    private static final int START_VERTEX = 0;
 10	
 11	    private MST() {}
 12	
 13	    static final class Edge {
 14	        final int from;
 15	        final int to;
 16	        final int weight;
 17	
 18	        Edge(int from, int to, int weight) {
 19	            this.from = from;
 20	            this.to = to;
 21	            this.weight = weight;
 22	        }
 23	    }
 24	
 25	    static final class Result {
 26	        final List<Edge> edges;
 27	        final int totalWeight;
 28	
 29	        Result(List<Edge> edges, int totalWeight) {
 30	            this.edges = List.copyOf(edges);
 31	            this.totalWeight = totalWeight;
 32	        }
 33	    }
 34	
 35	    private static int selectNextVertex(int[] key, boolean[] includedInMst) {
 36	        int minValue = Integer.MAX_VALUE;
 37	        int minIndex = -1;
 38	
 39	        for (int vertex = 0; vertex < includedInMst.length; vertex++) {
 40	            if (!includedInMst[vertex] && key[vertex] < minValue) {
 41	                minValue = key[vertex];
 42	                minIndex = vertex;
 43	            }
 44	        }
 45	
 46	        return minIndex;
 47	    }
 48	
 49	    private static void validateGraph(int[][] graph) {
 50	        if (graph == null) {
 51	            throw new IllegalArgumentException("Graph must not be null.");
 52	        }
 53	
 54	        if (graph.length == 0) {
 55	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
 56	        }
 57	
 58	        for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
 59	            int[] row = graph[rowIndex];
 60	            if (row == null) {
 61	                throw new IllegalArgumentException("Graph rows must not be null.");
 62	            }
 63	
 64	            if (row.length != graph.length) {
 65	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
 66	            }
 67	
 68	            for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
 69	                if (row[columnIndex] != graph[columnIndex][rowIndex]) {
 70	                    throw new IllegalArgumentException(
 71	                        "Graph must represent an undirected adjacency matrix."
 72	                    );
 73	                }
 74	            }
 75	        }
 76	    }
 77	
 78	    private static Result buildResult(int[] parent, int[][] graph) {
 79	        List<Edge> edges = new ArrayList<>();
 80	        int totalWeight = 0;
 81	
 82	        for (int vertex = 1; vertex < graph.length; vertex++) {
 83	            int from = parent[vertex];
 84	            int weight = graph[from][vertex];
 85	
 86	            edges.add(new Edge(from, vertex, weight));
 87	            totalWeight += weight;
 88	        }
 89	
 90	        return new Result(edges, totalWeight);
 91	    }
 92	
 93	    static Result computeMinimumSpanningTree(int[][] graph) {
 94	        validateGraph(graph);
 95	
 96	        int vertexCount = graph.length;
 97	        int[] parent = new int[vertexCount];
 98	        int[] key = new int[vertexCount];
 99	        boolean[] includedInMst = new boolean[vertexCount];
100	
101	        Arrays.fill(key, Integer.MAX_VALUE);
102	        key[START_VERTEX] = 0;
103	        parent[START_VERTEX] = ROOT_PARENT;
104	
105	        for (int count = 0; count < vertexCount - 1; count++) {
106	            int currentVertex = selectNextVertex(key, includedInMst);
107	
108	            if (currentVertex == -1) {
109	                throw new IllegalStateException("Graph must be connected.");
110	            }
111	
112	            includedInMst[currentVertex] = true;
113	
114	            for (int neighbor = 0; neighbor < vertexCount; neighbor++) {
115	                int edgeWeight = graph[currentVertex][neighbor];
116	
117	                if (edgeWeight != NO_EDGE && !includedInMst[neighbor]
118	                    && edgeWeight < key[neighbor]) {
119	                    parent[neighbor] = currentVertex;
120	                    key[neighbor] = edgeWeight;
121	                }
122	            }
123	        }
124	
125	        return buildResult(parent, graph);
126	    }
127	
128	    static String renderResult(Result result) {
129	        StringBuilder output = new StringBuilder("Edge \tWeight\n");
130	        for (Edge edge : result.edges) {
131	            output.append(edge.from)
132	                .append(" - ")
133	                .append(edge.to)
134	                .append('\t')
135	                .append(edge.weight)
136	                .append('\n');
137	        }
138	        return output.toString();
139	    }
140	
141	    static void printResult(PrintStream out, Result result) {
142	        out.print(renderResult(result));
143	    }
144	
145	    public static void main(String[] args)
146	    {
147	        int graph[][] = new int[][] { { 0, 2, 0, 6, 0 },
148	                                      { 2, 0, 3, 8, 5 },
149	                                      { 0, 3, 0, 0, 7 },
150	                                      { 6, 8, 0, 0, 9 },
151	                                      { 0, 5, 7, 9, 0 } };
152	
153	        Result result = computeMinimumSpanningTree(graph);
154	        printResult(System.out, result);
155	    }
156	}
